spec.setup_code:
var bar = new api.THREE.Mesh(
                  new api.THREE.BoxGeometry(1.5, 0.15, 0.15),
                  new api.THREE.MeshPhongMaterial({ color: 0xE8593C })
                );
                api.group.add(bar);
                var marker = new api.THREE.Mesh(
                  new api.THREE.SphereGeometry(0.1, 16, 16),
                  new api.THREE.MeshPhongMaterial({ color: 0x2E86AB })
                );
                api.group.add(marker);
                return {
                  update: function(t) {
                    bar.rotation.z = Math.sin(t * 0.01) * 0.3;
                    marker.position.x = Math.sin(t * 0.02) * 0.7;
                  }
                };

return {
                  draw: function(ctx, W, H, t, dt) {
                    ctx.fillStyle = '#F5F0E8';
                    ctx.fillRect(0, 0, W, H);
                    var n = Math.floor((t / 60) % 9);
                    ctx.fillStyle = '#111827';
                    ctx.font = 'bold 34px sans-serif';
                    ctx.textAlign = 'center';
                    ctx.fillText('3.0 x 10^' + n, W / 2, H / 2 - 10);
                    ctx.font = '16px sans-serif';
                    ctx.fillStyle = '#2E86AB';
                    ctx.fillText('= ' + (3 * Math.pow(10, n)).toLocaleString(), W / 2, H / 2 + 30);
                  }
                };

return {
                  draw: function(ctx, W, H) {
                    ctx.fillStyle = '#F9FAFB';
                    ctx.fillRect(0, 0, W, H);
                    var a = controls.coefficient !== undefined ? controls.coefficient : 3;
                    var n = controls.exponent !== undefined ? controls.exponent : 8;
                    ctx.fillStyle = '#111827';
                    ctx.font = 'bold 30px sans-serif';
                    ctx.textAlign = 'center';
                    ctx.fillText(a.toFixed(1) + ' x 10^' + n, W / 2, H / 2 - 15);
                    ctx.font = '16px sans-serif';
                    ctx.fillStyle = '#2E86AB';
                    ctx.fillText('= ' + (a * Math.pow(10, n)).toExponential(3), W / 2, H / 2 + 25);
                  }
                };
